BEGIN;
-- Routing tables contain opaque identifiers only. Customer data always has FORCE RLS.
CREATE TABLE chatbot_rate_buckets(bucket text PRIMARY KEY,window_at timestamptz NOT NULL,hits integer NOT NULL);
CREATE INDEX chatbot_rate_expiry ON chatbot_rate_buckets(window_at);
CREATE TABLE chatbot_subflows(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 2 AND 100),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE chatbot_subflow_versions(tenant_id uuid NOT NULL,subflow_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),definition jsonb NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,subflow_id,version),FOREIGN KEY(tenant_id,subflow_id) REFERENCES chatbot_subflows(tenant_id,id));
ALTER TABLE chatbot_flow_versions ADD COLUMN source_definition jsonb;
ALTER TABLE chatbot_integration_jobs ADD COLUMN contact_id uuid;
ALTER TABLE chatbot_integration_jobs ADD CONSTRAINT integration_contact_fk FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id);
CREATE TABLE chatbot_privacy_settings(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),retention_days integer NOT NULL DEFAULT 365 CHECK(retention_days BETWEEN 30 AND 3650),cleanup_enabled boolean NOT NULL DEFAULT false,last_cleanup_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE chatbot_media ADD COLUMN scan_status text NOT NULL DEFAULT 'PENDING' CHECK(scan_status IN ('PENDING','CLEAN','QUARANTINED'));
ALTER TABLE chatbot_media ADD COLUMN scanned_at timestamptz;
ALTER TABLE chatbot_media ADD COLUMN scan_result text;
CREATE TABLE chatbot_connectors(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL DEFAULT gen_random_uuid(),provider text NOT NULL CHECK(provider IN ('GOOGLE_SHEETS','HUBSPOT','WOOCOMMERCE','SHOPIFY')),name text NOT NULL,config jsonb NOT NULL DEFAULT '{}',credentials_encrypted text,enabled boolean NOT NULL DEFAULT true,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE chatbot_oauth_states(state_hash text PRIMARY KEY,tenant_id uuid NOT NULL,connector_id uuid NOT NULL,user_id uuid NOT NULL,provider text NOT NULL,verifier_encrypted text NOT NULL,expires_at timestamptz NOT NULL,FOREIGN KEY(tenant_id,connector_id) REFERENCES chatbot_connectors(tenant_id,id));
CREATE TABLE chatbot_connector_jobs(tenant_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),connector_id uuid NOT NULL,contact_id uuid NOT NULL,idempotency_key text NOT NULL,fields jsonb NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','DONE','FAILED','UNCERTAIN','CANCELLED')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,connector_id) REFERENCES chatbot_connectors(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id));
CREATE INDEX chatbot_connector_due ON chatbot_connector_jobs(tenant_id,next_attempt_at) WHERE status='PENDING';
CREATE TABLE chatbot_connector_links(tenant_id uuid NOT NULL,connector_id uuid NOT NULL,contact_id uuid NOT NULL,external_id text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,connector_id,contact_id),FOREIGN KEY(tenant_id,connector_id) REFERENCES chatbot_connectors(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id));
CREATE TABLE chatbot_social_accounts(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL DEFAULT gen_random_uuid(),channel text NOT NULL CHECK(channel IN ('MESSENGER','INSTAGRAM','TELEGRAM')),external_id text NOT NULL,token_encrypted text NOT NULL,webhook_secret_encrypted text NOT NULL,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE chatbot_social_routes(channel text NOT NULL,external_id text NOT NULL,tenant_id uuid NOT NULL,account_id uuid NOT NULL,PRIMARY KEY(channel,external_id),FOREIGN KEY(tenant_id,account_id) REFERENCES chatbot_social_accounts(tenant_id,id));
ALTER TABLE conversations DROP CONSTRAINT conversations_channel_check;
ALTER TABLE conversations ADD CONSTRAINT conversations_channel_check CHECK(channel IN ('INTERNAL','WHATSAPP','WEBSITE','MESSENGER','INSTAGRAM','TELEGRAM'));
ALTER TABLE conversations ADD COLUMN social_account_id uuid;
ALTER TABLE conversations ADD COLUMN external_sender_id text;
ALTER TABLE conversations ADD CONSTRAINT conversation_social_account_fk FOREIGN KEY(tenant_id,social_account_id) REFERENCES chatbot_social_accounts(tenant_id,id);
CREATE UNIQUE INDEX chatbot_social_conversation ON conversations(tenant_id,social_account_id,external_sender_id) WHERE social_account_id IS NOT NULL;
CREATE TABLE chatbot_social_actions(tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,token text NOT NULL,action_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,token),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE chatbot_social_receipts(tenant_id uuid NOT NULL,account_id uuid NOT NULL,event_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,account_id,event_id),FOREIGN KEY(tenant_id,account_id) REFERENCES chatbot_social_accounts(tenant_id,id));
CREATE TABLE chatbot_social_outbox(tenant_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),account_id uuid NOT NULL,conversation_id uuid NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENT','FAILED','UNCERTAIN','PROCESSING','CANCELLED')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,account_id) REFERENCES chatbot_social_accounts(tenant_id,id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id));
CREATE INDEX chatbot_social_due ON chatbot_social_outbox(tenant_id,next_attempt_at) WHERE status='PENDING';
CREATE TABLE chatbot_worker_health(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),last_seen_at timestamptz NOT NULL DEFAULT now(),last_error_code text);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['chatbot_subflows','chatbot_subflow_versions','chatbot_privacy_settings','chatbot_connectors','chatbot_connector_jobs','chatbot_connector_links','chatbot_social_accounts','chatbot_social_receipts','chatbot_social_actions','chatbot_social_outbox','chatbot_worker_health'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t); END LOOP; END $$;
COMMIT;
